creator_replace.using:
current_setting('app.account_role', true) = 'creator' and "content_drop_files"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and "content_drop_files"."slot_key" is not null and "content_drop_files"."replaced_at" is null and exists (
        select 1 from content_drops d where d.id = "content_drop_files"."drop_id" and d.creator_id = "content_drop_files"."creator_id" and d.state = 'filling'
      )

team_insert.withCheck:
current_setting('app.account_role', true) is distinct from 'creator' and nullif(current_setting('app.team_scope', true), '') in ('owner', 'agency') and "content_drop_files"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and "content_drop_files"."state" = 'awaiting' and exists (
        select 1 from content_drops d where d.id = "content_drop_files"."drop_id" and d.creator_id = "content_drop_files"."creator_id" and d.state = 'uploading'
      )
